export default async function f({ requestId, videos, music, rows, ack, resolution }, ctx) {
  if (!/^[A-Za-z0-9_-]{16,128}$/.test(requestId)) throw Error("Supply a unique request ID");
  const key = "autoclip:" + requestId,
    previous = await ctx.state.get(key),
    skip = () => ({
      key,
      requestId,
      video: {},
      audio: {},
      quote: {},
      videoIndex: 0,
      videoRows: [],
      musicRows: [],
      skip: true,
    });
  if (previous?.phase === "done") return skip();
  if (previous) {
    if (ack !== key || !["confirmed", "absent"].includes(resolution))
      throw Error("Inspect existing checkpoint " + key);
    if (resolution === "confirmed") {
      await ctx.state.set(key, { ...previous, phase: "done" });
      return skip();
    }
    await ctx.state.set(key, null);
  }
  const names = ["Index", "Qoute", "Author", "CreateStatus", "YoutubeURL"];
  if (!Array.isArray(rows) || !rows.length || !Array.isArray(videos) || !Array.isArray(music))
    throw Error("Missing sources");
  const h = rows[0],
    cols = names.map((x) => h.indexOf(x));
  if (cols.some((x) => x < 0)) throw Error("Missing quote columns");
  let q = rows
      .slice(1)
      .map((r, i) => ({ r, row: i + 2 }))
      .filter(
        (x) =>
          x.r[cols[0]] != null &&
          x.r[cols[0]] !== "" &&
          x.r[cols[1]] &&
          x.r[cols[2]] &&
          !x.r[cols[3]],
      ),
    v = videos.filter((x) => x?.id && x.webViewLink),
    m = music.filter((x) => x?.id && x.webViewLink);
  if (!q.length || !v.length || !m.length) throw Error("No eligible quote, video or music");
  const pick = (a) => a[Math.floor(Math.random() * a.length)],
    video = pick(v),
    audio = pick(m),
    chosen = pick(q),
    quote = {
      id: String(chosen.r[cols[0]]),
      text: String(chosen.r[cols[1]]),
      author: String(chosen.r[cols[2]]),
      sheetRow: chosen.row,
      indexColumn: cols[0] + 1,
      statusColumn: cols[3] + 1,
      urlColumn: cols[4] + 1,
    };
  await ctx.state.set(key, {
    phase: "pending",
    quoteId: quote.id,
    videoId: video.id,
    audioId: audio.id,
  });
  return {
    key,
    requestId,
    video,
    audio,
    quote,
    skip: false,
    videoIndex: v.findIndex((x) => x.id === video.id),
    videoRows: v.map((x) => [x.webViewLink, ""]),
    musicRows: m.map((x) => [x.webViewLink, ""]),
  };
}

