export default function f({ video, music, quote }) {
  const v = video?.secureUrl,
    id = music?.publicId;
  if (
    typeof v !== "string" ||
    !/^https:\/\/res\.cloudinary\.com\//.test(v) ||
    !id ||
    !quote?.text ||
    !quote?.author
  )
    throw Error("Invalid Cloudinary assets or quote");
  let marker = "/video/upload/",
    at = v.indexOf(marker);
  if (at < 0) throw Error("Unexpected video delivery URL");
  const esc = (x) => encodeURIComponent(x).replace(/%2F/gi, "%252F").replace(/%2C/gi, "%252C"),
    audio = id.replace(/\//g, ":");
  if (!/^[\w:.-]+$/.test(audio)) throw Error("Invalid audio public ID");
  const wrap = (s, n) => {
    let lines = [],
      line = "";
    for (const word of s.split(/\s+/)) {
      if (line && line.length + 1 + word.length > n) {
        lines.push(line);
        line = "";
      }
      line += (line ? " " : "") + word;
    }
    if (line) lines.push(line);
    return lines.join("\n");
  };
  let wrapped = wrap(quote.text, 24),
    text = esc(wrapped),
    author = esc(quote.author),
    authorY = Math.round(960 + (wrapped.split("\n").length * 77) / 2 + 20),
    trans =
      "c_fill,w_1080,h_1920,du_10/e_brightness:-30/l_audio:" +
      audio +
      "/e_volume:80/fl_layer_apply/l_text:Kanit@google_70_italic:" +
      text +
      ",co_white/fl_layer_apply/l_text:Kanit@google_50_italic:" +
      author +
      ",co_white,g_north_east,x_40,y_" +
      authorY +
      "/fl_layer_apply/";
  return {
    url:
      v.slice(0, at + marker.length) +
      trans +
      v.slice(at + marker.length).replace(/\.[A-Za-z0-9]+(?:\?.*)?$/, ".mp4"),
    title: Array.from(quote.text).slice(0, 100).join(""),
    description: quote.text + "\n" + quote.author,
  };
}

