export default function f({ previous, status, body, requestId }) {
  let s = previous ?? { count: 0 };
  s.count++;
  if (s.count > 120) throw Error("Inspect upload job");
  if (status !== 200 || !body || body.requestId !== requestId) throw Error("Invalid upload job");
  if (body.status === "done") {
    if (!body.videoId) throw Error("Missing YouTube ID");
    return { state: s, done: true, videoId: body.videoId };
  }
  if (body.status === "failed") throw Error("Inspect failed upload");
  return { state: s, done: false, videoId: "-" };
}

