export default function f({ quote, videoIndex, updatedRange, videoId, quoteSheet, videoSheet }) {
  let m = String(updatedRange).match(/!\$?[A-Z]+\$?(\d+)/i);
  if (!m || !videoId || !quote?.sheetRow) throw Error("Inspect video inventory");
  const col = (n) => {
      let s = "";
      while (n > 0) {
        n--;
        s = String.fromCharCode(65 + (n % 26)) + s;
        n = Math.floor(n / 26);
      }
      return s;
    },
    safe = (x) => "'" + x.replace(/'/g, "''") + "'",
    row = Number(m[1]) + videoIndex;
  return {
    quoteCheck: safe(quoteSheet) + "!A" + quote.sheetRow + ":Z" + quote.sheetRow,
    quoteStatus: safe(quoteSheet) + "!" + col(quote.statusColumn) + quote.sheetRow,
    quoteUrl: safe(quoteSheet) + "!" + col(quote.urlColumn) + quote.sheetRow,
    videoStatus: safe(videoSheet) + "!B" + row,
    url: "https://www.youtube.com/watch?v=" + encodeURIComponent(videoId),
  };
}

