export default async function f({ key, n }, ctx) {
  if (n !== 1) throw Error("Inspect sheet updates");
  let s = await ctx.state.get(key);
  if (s?.phase !== "pending") throw Error("Missing checkpoint");
  await ctx.state.set(key, { ...s, phase: "done" });
  return { ok: true };
}
